namespace local_eftimeclock\external;

use core_external\external_api;
use core_external\external_function_parameters;
use core_external\external_single_structure;
use core_external\external_value;
use local_eftimeclock\local\config;

/**
 * Stores the active time of a visit to an activity. The duration is
 * cumulative and is stored with max(); the client token makes the save
 * idempotent: all submissions of a visit (periodic XHR, beacon on leaving)
 * land on the same row, even if the browser does not read the response.
 *
 * The client is never trusted with the amount: what a save ADDS is bounded
 * by the server clock (the seconds elapsed since the user's latest save, in
 * any of their visits), so neither a hand-crafted call nor two devices at
 * once can credit more time than has really passed.
 *
 * @package    local_eftimeclock
 * @copyright  2026 Ana Rosiris Castro Mendez, eLearning Fácil (https://elearningfacil.com)
 * @author     Ana Rosiris Castro Mendez <info@elearningfacil.com>
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
class record_time extends external_api {
    /** @var int Hard cap of seconds per session (24 h). */
    const MAX_DURATION = 86400;

    /** @var int Most a visit may carry on its FIRST save (the client syncs every minute; a tick adds 120 s at most). */
    const FIRST_SAVE_MAX = 300;

    /** @var int Longest client token stored (the column is char(32)). */
    const TOKEN_MAXLENGTH = 32;

    /**
     * Describes the parameters of the external function.
     *
     * @return external_function_parameters
     */
    public static function execute_parameters(): external_function_parameters {
        return new external_function_parameters([
            'courseid'  => new external_value(PARAM_INT, 'course id'),
            'cmid'      => new external_value(PARAM_INT, 'course_module id'),
            'sessionid' => new external_value(PARAM_INT, 'existing session id, or 0 to create one'),
            'duration'  => new external_value(PARAM_INT, 'seconds of active time'),
            'clienttoken' => new external_value(
                PARAM_ALPHANUMEXT,
                'visit token generated by the client (idempotency)',
                VALUE_DEFAULT,
                ''
            ),
        ]);
    }

    /**
     * Stores or updates the active time of a visit.
     *
     * @param int $courseid Course id.
     * @param int $cmid Course module id.
     * @param int $sessionid Existing session id, or 0 to create a new one.
     * @param int $duration Active seconds of this visit.
     * @param string $clienttoken Client-generated visit token for idempotent upsert.
     * @return array sessionid and stored duration.
     */
    public static function execute(
        int $courseid,
        int $cmid,
        int $sessionid,
        int $duration,
        string $clienttoken = ''
    ): array {
        global $DB, $USER;

        $params = self::validate_parameters(self::execute_parameters(), [
            'courseid'    => $courseid,
            'cmid'        => $cmid,
            'sessionid'   => $sessionid,
            'duration'    => $duration,
            'clienttoken' => $clienttoken,
        ]);

        $courseid = (int) $params['courseid'];
        $cmid     = (int) $params['cmid'];
        $nothing  = ['sessionid' => (int) $params['sessionid'], 'duration' => 0];

        $coursecontext = \context_course::instance($courseid);

        // The free plugin only measures activities: cmid required and belonging to the course.
        $cm = get_coursemodule_from_id('', $cmid, 0, false, IGNORE_MISSING);
        if (!$cm || (int) $cm->course !== $courseid) {
            return $nothing;
        }
        $context = \context_module::instance($cm->id);
        self::validate_context($context);

        // Security boundary, the same the clock injection applies: an active
        // student enrolment with the capability; never staff (report viewers)
        // nor administrators, whatever the client sends.
        if (
            !is_enrolled($coursecontext, $USER->id, '', true)
                || !has_capability('local/eftimeclock:recordtime', $context)
                || has_capability('local/eftimeclock:viewreport', $coursecontext)
                || is_siteadmin()
        ) {
            return $nothing;
        }
        // Clock off for this course (or the PRO suite measuring instead):
        // nothing is recorded, also for a tab opened before switching it off.
        if (!config::for_course($courseid)['enabled']) {
            return $nothing;
        }

        $token = (string) $params['clienttoken'];
        if (\core_text::strlen($token) > self::TOKEN_MAXLENGTH) {
            // Longer than the column: refused here, not as a database error.
            return $nothing;
        }
        $duration = max(0, min((int) $params['duration'], self::MAX_DURATION));
        $now      = time();

        // Resolve the row of this visit: by sessionid (fast path for XHR,
        // always of THIS course and activity: a stale id of another course
        // never receives these seconds) or by clienttoken (idempotent
        // fallback for sendBeacon).
        $session = false;
        if ($params['sessionid'] > 0) {
            $session = $DB->get_record(
                'local_eftimeclock_session',
                ['id' => $params['sessionid'], 'userid' => $USER->id, 'courseid' => $courseid, 'cmid' => $cmid],
                '*',
                IGNORE_MISSING
            );
        }
        if (!$session && $token !== '') {
            $session = $DB->get_record(
                'local_eftimeclock_session',
                ['userid' => $USER->id, 'courseid' => $courseid, 'cmid' => $cmid, 'clienttoken' => $token],
                '*',
                IGNORE_MISSING
            );
        }

        if ($session) {
            return self::credit($session, $duration, $now);
        }

        $record = (object) [
            'userid'       => $USER->id,
            'courseid'     => $courseid,
            'cmid'         => $cmid,
            'duration'     => self::first_save($duration, $now),
            'clienttoken'  => ($token !== '' ? $token : null),
            'timecreated'  => $now,
            'timemodified' => $now,
        ];
        try {
            $record->id = $DB->insert_record('local_eftimeclock_session', $record);
        } catch (\dml_exception $e) {
            // Race: another submission with the same token inserted the row
            // between the SELECT and this INSERT (unique index). Turn into update.
            if ($token === '') {
                throw $e;
            }
            $session = $DB->get_record(
                'local_eftimeclock_session',
                ['userid' => $USER->id, 'courseid' => $courseid, 'cmid' => $cmid, 'clienttoken' => $token],
                '*',
                MUST_EXIST
            );
            return self::credit($session, $duration, $now);
        }

        return ['sessionid' => (int) $record->id, 'duration' => (int) $record->duration];
    }

    /**
     * Seconds elapsed since the user's latest save, in any visit of any
     * course: the most a save may add. Nothing saved yet = no bound.
     *
     * @param int $userid User.
     * @param int $now Time of this save.
     * @return int|null Seconds, or null when the user has no row at all.
     */
    protected static function elapsed_since_last_save(int $userid, int $now): ?int {
        global $DB;
        $last = $DB->get_field_sql(
            'SELECT MAX(timemodified) FROM {local_eftimeclock_session} WHERE userid = :userid',
            ['userid' => $userid]
        );
        if ($last === null || $last === false) {
            return null;
        }
        return max(0, $now - (int) $last);
    }

    /**
     * Seconds a brand-new visit may start with: what the client sends,
     * bounded by the first-save ceiling and by the time elapsed since the
     * user's latest save.
     *
     * @param int $duration Seconds the client sent (already within MAX_DURATION).
     * @param int $now Time of this save.
     * @return int
     */
    protected static function first_save(int $duration, int $now): int {
        global $USER;
        $allowed = min($duration, self::FIRST_SAVE_MAX);
        $elapsed = self::elapsed_since_last_save((int) $USER->id, $now);
        if ($elapsed !== null) {
            $allowed = min($allowed, $elapsed);
        }
        return max(0, $allowed);
    }

    /**
     * Credits a save to an existing visit: only what it ADDS over the stored
     * cumulative value, and never more than the seconds elapsed since the
     * user's latest save (a replay adds nothing; a second device only gets
     * what has passed since the first one wrote).
     *
     * @param \stdClass $session Visit row.
     * @param int $duration Cumulative seconds the client sent (within MAX_DURATION).
     * @param int $now Time of this save.
     * @return array sessionid and stored duration.
     */
    protected static function credit(\stdClass $session, int $duration, int $now): array {
        global $DB;
        $added = max(0, $duration - (int) $session->duration);
        $elapsed = self::elapsed_since_last_save((int) $session->userid, $now);
        if ($elapsed !== null) {
            $added = min($added, $elapsed);
        }
        $session->duration     = min(self::MAX_DURATION, (int) $session->duration + $added);
        $session->timemodified = $now;
        $DB->update_record('local_eftimeclock_session', $session);
        return ['sessionid' => (int) $session->id, 'duration' => (int) $session->duration];
    }

    /**
     * Describes the return value of the external function.
     *
     * @return external_single_structure
     */
    public static function execute_returns(): external_single_structure {
        return new external_single_structure([
            'sessionid' => new external_value(PARAM_INT, 'id of the stored session'),
            'duration'  => new external_value(PARAM_INT, 'stored seconds'),
        ]);
    }
}
